# Secret keys. Git ignores this file, so it never goes to GitHub.
# Paste each key after the =<set>
TYPESAFE_API_KEY=<set>
ANTHROPIC_API_KEY=<set>
{
  "name": "schoolwork-assistant",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node --env-file=.env --watch-path=src --watch-path=web src/server.ts",
    "import": "node --env-file=.env src/import-cli.ts",
    "typecheck": "tsc",
    "test": "node --test \"test/**/*.test.ts\"",
    "format": "prettier --write src test web"
  },
  "devDependencies": {
    "@types/node": "^26.6.5",
    "esbuild": "^0.28.2",
    "prettier": "^3.9.10",
    "typescript": "^7.0.2"
  },
  "dependencies": {
    "@anthropic-ai/sdk": "^0.135.0",
    "@typesafe-ai/sdk": "^0.7.0",
    "sharp": "^0.35.5",
    "zod": "^4.6.7"
  }
}
// Turns a screenshot or the text of any course page into a checked list of
// assignments. Claude Haiku reads it and lists what it sees (TypeSafe answers
// questions but doesn't write text); TypeSafe then checks each row against the
// same screenshot or text, and rows it doubts are flagged for the student.
import Anthropic from "@anthropic-ai/sdk";
import { zodOutputFormat } from "@anthropic-ai/sdk/helpers/zod";
import { choice, image, noul, TypeSafeClient } from "@typesafe-ai/sdk";
import sharp from "sharp";
import { z } from "zod";
import { STATUSES, type Status } from "./assignment.ts";

const EXTRACT_MODEL = "claude-haiku-5-5";
const MAX_IMAGE_SIDE = 1568;
// ponytail: one time zone for every page, the student's; a page showing times
// in another zone would be read as local. Add per-page zones if that happens.
export const TIME_ZONE = process.env.TIME_ZONE ?? "America/Chicago";
// ponytail: one fixed cutoff for "confident"; tune it once there's a test set
// of real screenshots with known answers.
export const CONFIDENT = 0.7;

const ExtractedSchema = z.object({
  name: z.string(),
  course: z.string(),
  dueAt: z.string().nullable(),
  status: z.enum(STATUSES),
  kind: z.enum(["task", "grade_total", "optional"]),
});
const ExtractionSchema = z.object({ assignments: z.array(ExtractedSchema) });

export type Extracted = z.infer<typeof ExtractedSchema>;

/** TypeSafe's answers about one row, checked against the image. */
export interface RowCheck {
  /** Probability the screenshot shows this name with this due date. */
  dueProbability: number;
  /** TypeSafe's own pick for the status, and its probability. */
  statusChoice: Status;
  statusProbability: number;
  /** Probability the row is a gradebook total rather than one piece of work. */
  totalProbability: number;
}

export interface CheckedAssignment extends RowCheck {
  name: string;
  course: string;
  dueAt: string | null;
  status: Status;
  include: boolean;
  flag: string | null;
}

const STATUS_MEANINGS: Record<Status, string> = {
  open: "It can be worked on now and isn't finished, for example an empty progress bar or 'Not started'.",
  not_open_yet:
    "It isn't available yet, for example 'Not available until …' or a start date that hasn't come.",
  closed:
    "It is finished or can't be worked on: locked, submitted, completed (a full progress bar or a 100% score), or past due.",
  unknown: "The page doesn't show whether it can be worked on.",
};

export type ImageFormat = "png" | "jpeg";

/** What an import reads: a screenshot (already resized) or a page's text. */
type Source =
  { kind: "screenshot"; bytes: Uint8Array } | { kind: "page"; text: string };

/** Pasted page text past this is cut off; course pages are far shorter. */
export const MAX_PAGE_CHARACTERS = 60_000;

/** Reads the format from the file's first bytes; both APIs accept only these two. */
export function imageFormat(bytes: Uint8Array): ImageFormat | null {
  if (bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4e) return "png";
  if (bytes[0] === 0xff && bytes[1] === 0xd8) return "jpeg";
  return null;
}

/**
 * Combines Claude's reading with TypeSafe's check. A confident TypeSafe answer
 * fills in what Claude couldn't tell; an unsure one (near 50%) defers to
 * Claude. Rows both models call grade totals are left out.
// How long each assignment will take, judged once by TypeSafe and saved.
// The learning milestone will correct these with real focus-timer times.
import { score, TypeSafeClient } from "@typesafe-ai/sdk";
import type { SavedAssignment } from "./assignment.ts";

/** Minutes for each level of the scale below, shortest first. */
const LEVEL_MINUTES = [10, 30, 60, 150, 360];
const LEVELS = [
  "About 10 minutes: a short quiz, a quick post, or a small check-in.",
  "About 30 minutes: a typical online homework set or a short discussion post or recording.",
  "About 1 hour: a longer problem set or a short written response.",
  "About 2 to 3 hours: a lab report, a project milestone, or a short paper.",
  "Most of a day or more: a large project, a long paper, or studying for an exam.",
] as const;

/**
 * Combines the level probabilities on a log scale (a weighted geometric mean),
 * so a small chance of "most of a day" doesn't swamp a likely 30 minutes.
 */
export function minutesFromProbabilities(probabilities: number[]): number {
  const total = probabilities.reduce((sum, p) => sum + p, 0) || 1;
  const logMinutes = probabilities.reduce(
    (sum, p, level) => sum + (p / total) * Math.log(LEVEL_MINUTES[level]),
    0,
  );
  return Math.round(Math.exp(logMinutes));
}

/** Estimates, keyed by assignment id; tests swap in a fake. */
export type EstimateMinutes = (
  assignments: SavedAssignment[],
) => Promise<Map<number, number>>;

export const typeSafeEstimateMinutes: EstimateMinutes = async (assignments) => {
  if (assignments.length === 0) return new Map();
  const client = new TypeSafeClient();
  const { answers } = await client.systemOne({
    state: {
      assignments: assignments.map((assignment) => ({
        name: assignment.name,
        course: assignment.course || "not shown",
      })),
    },
    questions: Object.fromEntries(
      assignments.map((_, k) => [
        `minutes${k}`,
        score(
          `How long will a typical college student need to finish \`assignments[${k}]\`?`,
          LEVELS,
        ),
      ]),
    ),
  });
  return new Map(
    assignments.map((assignment, k) => {
      // Probabilities come keyed by level number ("0" to "4").
      const probabilities: Record<number, number> =
        answers[`minutes${k}`].probabilities;
      const ordered = LEVELS.map((_, level) => probabilities[level] ?? 0);
      return [assignment.id, minutesFromProbabilities(ordered)];

